+using Microsoft.EntityFrameworkCore;
+
+// EF Core 9 Cosmos breaking changes addressed here:
+//
+// 1. Discriminator property renamed: EF Core 9 now uses "$type" instead of
+//    "Discriminator". For existing documents that already store "Discriminator",
+//    configure the old property name explicitly.
+//
+// 2. Synchronous I/O removed: Sync methods (ToList(), First(), SaveChanges(), etc.)
+//    now throw InvalidOperationException on the Cosmos provider.
+//    Use async equivalents (ToListAsync(), FirstAsync(), SaveChangesAsync()).
+
+class CosmosDbContext : DbContext
+{
+    public DbSet<Product> Products => Set<Product>();
+
+    protected override void OnConfiguring(DbContextOptionsBuilder options)
+    {
+        options.UseCosmos(
+            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
+            "MyDatabase");
+    }
+
+    protected override void OnModelCreating(ModelBuilder modelBuilder)
+    {
+        // Breaking change fix: existing documents use "Discriminator" but
+        // EF Core 9 defaults to "$type". Preserve the old property name.
+        modelBuilder.Entity<Product>(b =>
+        {
+            b.ToContainer("Products");
+            b.HasDiscriminator<string>("Discriminator");
+        });
+    }
+}
+
+class Product
+{
+    public string Id { get; set; } = default!;
+    public string Name { get; set; } = default!;
+    public decimal Price { get; set; }
+}
+
+// Example showing the sync → async migration required for Cosmos provider:
+class ProductService
+{
+    private readonly CosmosDbContext _db;
+    public ProductService(CosmosDbContext db) => _db = db;
+
+    // BEFORE (EF Core 8 — throws in EF Core 9):
+    //   var products = _db.Products.Where(p => p.Price > 10).ToList();
+    //   _db.Products.Add(new Product { ... });
+    //   _db.SaveChanges();
+
+    // AFTER (EF Core 9 — async only):
+    public async Task<List<Product>> GetExpensiveProductsAsync()
+    {
+        return await _db.Products
+            .Where(p => p.Price > 10)
+            .ToListAsync();
+    }
+
+    public async Task AddProductAsync(Product product)
+    {
+        _db.Products.Add(product);
+        await _db.SaveChangesAsync();
+    }
+}
